create table RB_BUS_CLIENT_ACCT (BASE_ACCT_NO VARCHAR(50) not null  ,IS_CORP_SETTLE_CARD VARCHAR(1) not null  ,CLIENT_NO VARCHAR(22) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,ACCT_DOMAIN VARCHAR(20) not null  ,ACCT_OPEN_DATE TIMESTAMP(3) not null  ,CLOSE_BRANCH VARCHAR(30) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,CLIENT_ACCT_STATUS VARCHAR(20) null  ,ACCT_BRANCH VARCHAR(30) not null  ,DOC_TYPE VARCHAR(4) null  ,VOUCHER_NO VARCHAR(60) null  ,CLIENT_VOUCHER_STATUS VARCHAR(10) null  ,CLIENT_TYPE VARCHAR(3) not null  ,DOC_CLASS VARCHAR(3) null  ,CARD_PB_UNION_FLAG VARCHAR(1) not null  ,WITHDRAWAL_TYPE VARCHAR(1) null  , primary key(BASE_ACCT_NO,CLIENT_NO));